<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,reactive,ref,watch} from 'vue';
import FormModal from './FormModal.vue';
import {newClientId} from '../utils/client-id';
import {vFormValidation,inlineErrorMessage,presentFormError} from '../utils/form-validation';
type Rec=Record<string,any>;
const props=defineProps<{user:Rec,view:string,lineId:string,focusTab?:string,focusTower?:string}>();
const emit=defineEmits<{(e:'update:lineId',id:string):void,(e:'update:focusTab',tab:string):void,(e:'workspace',value:Rec):void,(e:'changed'):void,(e:'demands',value:Rec):void}>();
const lines=ref<Rec[]>([]),voltage=ref<Rec[]>([]),items=ref<Rec[]>([]),allTowers=ref<Rec[]>([]),allSpans=ref<Rec[]>([]),workspace=ref<Rec|null>(null);
const loading=ref(false),busy=ref(false),error=ref(''),success=ref(''),tab=ref(props.focusTab||'towers');
const filter=ref(''),voltageFilter=ref(''),query=ref(''),queryLine=ref(''),queryPage=ref(1),towerSearch=ref(''),showRetired=ref(false);
const selectedTowers=reactive<Record<string,boolean>>({}),selectedSpans=reactive<Record<string,boolean>>({}),highlight=ref<string[]>([]);
const editor=ref(''),form=reactive<Rec>({}),rows=ref<Rec[]>([]),common=reactive<Rec>({}),preview=ref<Rec|null>(null),previewHash=ref(''),initialSnapshot=ref(''),discard=ref(false),requestKey=ref('');
const replacementTargets=ref<Rec[]>([]);
const towerView=ref<Rec|null>(null),sourceLine=ref(''),rangeStart=ref('1'),rangeEnd=ref('10'),numberWidth=ref('3'),numberPrefix=ref(''),pasteNumbers=ref(''),inputMode=ref('range'),pasteLengths=ref('');
const lineChoice=computed(()=>workspace.value?.line||null),canWrite=computed(()=>['admin','editor'].includes(props.user.role));
const visibleError=computed(()=>error.value===inlineErrorMessage.value?'':error.value);
const nodes=computed<Rec[]>(()=>workspace.value?[...(workspace.value.junction?[{...workspace.value.junction,is_junction:true}]:[]),...workspace.value.towers]:[]);
const ownTowers=computed<Rec[]>(()=>workspace.value?.towers||[]);
const currentSpans=computed<Rec[]>(()=> (workspace.value?.spans||[]).filter((s:Rec)=>showRetired.value||s.status!=='retired'));
const filteredTowers=computed(()=>nodes.value.filter(t=>!towerSearch.value||[t.tower_no,t.model,t.tower_type].some(v=>String(v||'').includes(towerSearch.value))));
const chosenTowers=computed(()=>nodes.value.filter(t=>selectedTowers[t.id]&&t.status==='active'));
const chosenSpans=computed(()=>currentSpans.value.filter(s=>selectedSpans[s.id]&&s.status!=='retired'));
const matching=(l:Rec)=> (!filter.value||l.name.includes(filter.value))&&(!voltageFilter.value||l.voltage_level_id===voltageFilter.value);
const tree=computed<Rec[]>(()=>lines.value.filter(l=>l.line_kind==='main').map(main=>({...main,children:lines.value.filter(l=>l.parent_line_id===main.id&&matching(l))})).filter(main=>matching(main)||main.children.length));
const queryRows=computed(()=> (props.view==='towers'?allTowers.value:allSpans.value.filter(s=>s.status!=='retired')).filter(r=>(!queryLine.value||r.line_id===queryLine.value)&&(!query.value||[r.line_name,r.tower_no,r.start_tower_no,r.end_tower_no,r.model,r.tower_type].some(v=>String(v||'').includes(query.value)))));
const pageRows=computed(()=>queryRows.value.slice((queryPage.value-1)*30,queryPage.value*30));
const lookup=computed(()=>allTowers.value.filter(t=>t.status==='active'&&t.physical_tower_id&&t.line_status==='active'&&t.setup_status==='ready'&&t.line_id!==props.lineId&&(!sourceLine.value||t.line_id===sourceLine.value)));
const endpointOptions=computed(()=>nodes.value.filter(t=>t.status==='active'));
const ready=computed(()=>lineChoice.value?.status==='active'&&lineChoice.value?.setup_status==='ready');
const commonChanged=computed(()=>editor.value==='tower-edit'&&towerView.value&&JSON.stringify(physicalForm(towerView.value.physical))!==JSON.stringify(form.physical));
const title=computed(()=>({line:form.id?'编辑线路':'新建线路','tower-add':'新增杆塔','tower-batch':'批量添加杆塔','tower-edit':'编辑杆塔','tower-replace':'本线路单回路换塔','whole-replace':'整塔更换（确认全部共塔回路）',shared:'关联共塔',reorder:'调整沿线顺序','span-add':'新增档距','span-edit':'编辑档距长度','span-batch':'按杆塔顺序生成档距',replace:'拆档 / 合档变更',delete:'确认删除'} as Rec)[editor.value]||'');
const selectedRows=computed(()=>rows.value.filter(r=>r.selected!==false&&!r.existing_id));
function snapshot(){return JSON.stringify({form,rows:rows.value,common,inputMode:inputMode.value,rangeStart:rangeStart.value,rangeEnd:rangeEnd.value,numberWidth:numberWidth.value,numberPrefix:numberPrefix.value,pasteNumbers:pasteNumbers.value})}
const dirty=computed(()=>!!editor.value&&snapshot()!==initialSnapshot.value);
const qty=(n:any)=>n===null||n===undefined?'未填写':String(n/10000);
const stateName=(s:string)=>({active:'在用',inactive:'停用',draft:'待完善',retired:'历史'} as Rec)[s]||s;
const optionItems=(type:string)=>items.value.filter(i=>i.type_id===type&&i.status==='active');
function notify(message:string){success.value=message}
function report(e:any){error.value=e?.message||'请求失败';presentFormError(error.value,e?.details)}
async function api(path:string,method='GET',body?:any){const r=await fetch('/api'+path,{method,headers:body===undefined?{}:{'content-type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw Object.assign(Error(d.error),{details:d.details});return d}
let loadVersion=0;
async function loadData(id=props.lineId){
 const ticket=++loadVersion;loading.value=true;
 try{const [ls,vs,ds,ts,ss]=await Promise.all([api('/ledger/lines'),api('/voltage-levels'),api('/dictionary-items'),api('/ledger/towers'),api('/ledger/spans?status=all')]);if(ticket!==loadVersion)return;lines.value=ls;voltage.value=vs;items.value=ds;allTowers.value=ts;allSpans.value=ss;
 const target=ls.some((l:Rec)=>l.id===id)?id:ls[0]?.id||'';if(target!==props.lineId)emit('update:lineId',target);
 const w=target?await api('/ledger/lines/'+target):null;if(ticket!==loadVersion)return;workspace.value=w;
 for(const key of Object.keys(selectedTowers))if(!w||!nodes.value.some(t=>t.id===key))delete selectedTowers[key];
 for(const key of Object.keys(selectedSpans))if(!w||!w.spans.some((s:Rec)=>s.id===key&&s.status!=='retired'))delete selectedSpans[key];
 }catch(e){if(ticket===loadVersion)report(e)}finally{if(ticket===loadVersion)loading.value=false}
}
async function selectLine(id:string){if(id===props.lineId&&workspace.value?.line.id===id)return;emit('update:lineId',id);Object.keys(selectedTowers).forEach(k=>delete selectedTowers[k]);Object.keys(selectedSpans).forEach(k=>delete selectedSpans[k]);towerView.value=null;highlight.value=[];towerSearch.value='';await loadData(id)}
async function openQuery(row:Rec){const kind=props.view;emit('workspace',{lineId:row.line_id,tab:props.view==='towers'?'towers':'spans',towerId:props.view==='towers'?row.id:''});await selectLine(row.line_id);tab.value=kind==='towers'?'towers':'spans';if(row.tower_no)await showTower(row.id)}
function resetEditor(kind:string,values:Rec={},list:Rec[]=[]){error.value='';editor.value=kind;Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,values);rows.value=list;Object.keys(common).forEach(k=>delete common[k]);Object.assign(common,{tower_type:'',model:'',height:'',purpose:'',commissioned_on:'',longitude:'',latitude:''});preview.value=null;previewHash.value='';sourceLine.value='';requestKey.value=newClientId();pasteLengths.value='';initialSnapshot.value=snapshot()}
function closeEditor(){if(busy.value)return;if(dirty.value){discard.value=true;return}editor.value='';error.value=''}
function discardEditor(){discard.value=false;editor.value='';error.value=''}
async function saved(result:Rec,message:string){editor.value='';error.value='';highlight.value=result.ids||[];await loadData(result.line_id||result.id||props.lineId);emit('changed');notify(message)}
function lineForm(branch=false){resetEditor('line',{line_kind:branch?'branch':'main',parent_line_id:branch?props.lineId:'',junction_tower_id:'',name:'',voltage_level_id:branch?lineChoice.value?.voltage_level_id:'',start_label:'',end_label:'',status:'active',setup_status:'ready'})}
function editLine(){if(lineChoice.value)resetEditor('line',{...lineChoice.value,reason:''})}
async function saveLine(draft=false){if(!canWrite.value)return;busy.value=true;error.value='';try{const body={...form,draft,setup_status:draft?'draft':'ready',idempotency_key:requestKey.value};const r=await api('/ledger/lines'+(form.id?'/'+form.id:''),form.id?'PATCH':'POST',body);emit('update:lineId',r.id);await saved({line_id:r.id},draft?'支线草稿已保存，请继续确认接入杆塔':'线路已保存');tab.value='towers'}catch(e){report(e)}finally{busy.value=false}}
function physicalForm(p:Rec={}){return {tower_type:p?.tower_type||'',model:p?.model||'',height:p?.height_scaled?qty(p.height_scaled):'',purpose:p?.purpose||'',asset_no:p?.asset_no||'',commissioned_on:p?.commissioned_on||'',longitude:p?.longitude??'',latitude:p?.latitude??''}}
function addTower(batch=false,after=''){resetEditor(batch?'tower-batch':'tower-add',{after_tower_id:after,mode:'new'},batch?[]:[{tower_no:'',physical_tower_id:'',circuit_position:'',selected:true}])}
function generateNumbers(){error.value='';const names:string[]=[];if(inputMode.value==='paste'){names.push(...pasteNumbers.value.split(/\r?\n|\t/).map(s=>s.trim()).filter(Boolean))}else{const a=Number(rangeStart.value),b=Number(rangeEnd.value),width=Number(numberWidth.value);if(!Number.isInteger(a)||!Number.isInteger(b)||a<0||b<a||b-a>=500||!Number.isInteger(width)||width<1||width>10){error.value='编号范围须递增，每批最多500基；补零位数为1至10';return}for(let i=a;i<=b;i++)names.push(numberPrefix.value+String(i).padStart(width,'0'))}if(!names.length||names.length>500){error.value='请提供1至500个杆塔编号';return}rows.value=names.map(tower_no=>({tower_no,...common,physical_tower_id:'',circuit_position:'',selected:true}));preview.value=null}
function applyCommon(overwrite=false){for(const row of rows.value)if(!overwrite||row.selected)for(const [key,value] of Object.entries(common))if(overwrite||!row[key])row[key]=value;preview.value=null}
function towerPayload(){return {version:lineChoice.value!.version,topology_token:workspace.value!.topology_token,after_tower_id:form.after_tower_id||null,common:{...common},rows:rows.value.map(r=>({...r,physical_tower_id:form.mode==='existing'||editor.value==='tower-batch'?r.physical_tower_id||null:null})),idempotency_key:requestKey.value}}
async function saveTowers(){busy.value=true;error.value='';try{const body=towerPayload(),fingerprint=JSON.stringify(body);if(editor.value==='tower-batch'&&previewHash.value!==fingerprint){preview.value=await api('/ledger/lines/'+props.lineId+'/towers/preview','POST',body);previewHash.value=fingerprint;return}const r=await api('/ledger/lines/'+props.lineId+'/towers','POST',body);await saved(r,'已保存 '+r.count+' 基杆塔')}catch(e){report(e)}finally{busy.value=false}}
async function showTower(id:string){try{towerView.value=await api('/ledger/towers/'+id)}catch(e){report(e)}}
async function editTower(row:Rec,replace=false){await showTower(row.id);if(!towerView.value)return;
 if(replace&&towerView.value.shared_with.filter((r:Rec)=>r.status==='active').length>1){await openWholeReplacement();return}
 resetEditor(replace?'tower-replace':'tower-edit',{id:row.id,version:towerView.value.version,tower_no:towerView.value.tower_no,circuit_position:towerView.value.circuit_position||'',status:towerView.value.status,physical_version:towerView.value.physical?.version,physical:replace?physicalForm():physicalForm(towerView.value.physical),reason:'',confirm_shared:false})}
async function openWholeReplacement(){
 if(!towerView.value?.physical?.id)return;
 error.value='';busy.value=true;
 try{
  const id=towerView.value.physical.id;
  const [impact,allPhysical]=await Promise.all([api('/physical-towers/'+id+'/replace'),api('/physical-towers')]);
  replacementTargets.value=allPhysical.filter((x:Rec)=>x.id!==id&&x.status==='active');
  resetEditor('whole-replace',{source_id:id,source_version:impact.source.version,
    target_physical_tower_id:'',reason:''},impact.affected.map((x:Rec)=>({...x,checked:false})));
 }catch(e){report(e)}finally{busy.value=false}
}
async function saveWholeReplacement(){
 if(rows.value.some((x:Rec)=>!x.checked)){error.value='必须逐条勾选确认全部受影响回路';return}
 busy.value=true;error.value='';
 try{
  await api('/physical-towers/'+form.source_id+'/replace','POST',{
   source_version:form.source_version,target_physical_tower_id:form.target_physical_tower_id,
   confirmed_towers:rows.value.map((x:Rec)=>({id:x.id,version:x.version})),reason:form.reason
  });
  editor.value='';await loadData(props.lineId);emit('changed');
  if(towerView.value)await showTower(towerView.value.id);
  notify('整塔更换完成，共塔回路已在同一事务更新，历史保留');
 }catch(e){report(e)}finally{busy.value=false}
}
async function saveTower(){busy.value=true;error.value='';try{const r=await api('/ledger/towers/'+form.id,'PATCH',{...form,replace_physical:editor.value==='tower-replace',idempotency_key:requestKey.value});await saved(r,'杆塔变更已保存并留痕');await showTower(r.id)}catch(e){report(e)}finally{busy.value=false}}
function openReorder(){resetEditor('reorder',{reason:''},ownTowers.value.filter(t=>t.status!=='inactive').map(t=>({...t})))}
function move(index:number,delta:number){const target=index+delta;if(target<0||target>=rows.value.length)return;const [r]=rows.value.splice(index,1);rows.value.splice(target,0,r)}
async function saveOrder(){busy.value=true;try{const r=await api('/ledger/lines/'+props.lineId+'/reorder','POST',{version:lineChoice.value!.version,topology_token:workspace.value!.topology_token,ordered_ids:rows.value.map(r=>r.id),reason:form.reason,idempotency_key:requestKey.value});await saved(r,'沿线顺序已更新，已有档距保持原连接')}catch(e){report(e)}finally{busy.value=false}}
function openShared(row?:Rec){const candidates=row?[row]:chosenTowers.value.filter(t=>!t.is_junction);resetEditor('shared',{reason:'',change_kind:'correction'},candidates.map(source=>({source_id:source.id,source_version:source.version,source_name:source.tower_no,target_id:''})))}
async function saveShared(){busy.value=true;error.value='';try{const pairs=rows.value.map(r=>{const target=allTowers.value.find(t=>t.id===r.target_id);return {source_id:r.source_id,source_version:r.source_version,target_id:r.target_id,target_version:target?.version,target_physical_version:target?.physical_version}}),body={pairs,change_kind:form.change_kind,reason:form.reason,idempotency_key:requestKey.value},fingerprint=JSON.stringify(body);if(previewHash.value!==fingerprint){preview.value=await api('/ledger/shared/preview','POST',body);previewHash.value=fingerprint;return}await api('/ledger/shared/bind','POST',body);await saved({line_id:props.lineId},'共塔关系已保存；原需求仍保留当时的位置依据');towerView.value=null}catch(e){report(e)}finally{busy.value=false}}
function addSpan(){const selected=chosenTowers.value;resetEditor('span-add',{start_tower_id:selected[0]?.id||'',end_tower_id:selected[1]?.id||'',length:''})}
function editSpan(s:Rec){resetEditor('span-edit',{...s,length:s.length_scaled===null?'':qty(s.length_scaled),reason:''})}
async function generateSpans(){error.value='';try{const result=await api('/ledger/lines/'+props.lineId+'/spans/preview','POST',{version:lineChoice.value!.version,topology_token:workspace.value!.topology_token,...(chosenTowers.value.length?{tower_ids:chosenTowers.value.map(t=>t.id)}:{})});resetEditor('span-batch',{topology_token:result.topology_token},result.candidates.map((r:Rec)=>({...r,selected:!r.existing_id})));initialSnapshot.value=snapshot()}catch(e){report(e)}}
function pasteSpanLengths(){const values=pasteLengths.value.split(/\r?\n|\t/).map(v=>v.trim()).filter(Boolean),selected=selectedRows.value;if(values.length!==selected.length){error.value='粘贴的长度行数应与所选新档距数量一致';return}selected.forEach((row,i)=>row.length=values[i]);error.value=''}
async function saveSpans(){busy.value=true;error.value='';try{let r;if(editor.value==='span-edit')r=await api('/ledger/spans/'+form.id,'PATCH',{version:form.version,length:form.length,reason:form.reason,idempotency_key:requestKey.value});else r=await api('/ledger/lines/'+props.lineId+'/spans','POST',{version:lineChoice.value!.version,topology_token:workspace.value!.topology_token,rows:editor.value==='span-add'?[{...form}]:selectedRows.value,idempotency_key:requestKey.value});await saved({...r,line_id:props.lineId},'档距已保存，未填写长度的档距保留为待完善');tab.value='spans'}catch(e){report(e)}finally{busy.value=false}}
function openReplace(){const old=chosenSpans.value;if(!old.length)return;const degree=new Map<string,number>();for(const s of old)for(const id of [s.start_tower_id,s.end_tower_id])degree.set(id,(degree.get(id)||0)+1);const ends=[...degree].filter(([,n])=>n===1).map(([id])=>id);if(ends.length!==2||[...degree.values()].some(n=>n>2)){error.value='请选择一条连续路径上的档距';return}resetEditor('replace',{old_ids:old.map(s=>s.id),reason:'',old_names:old.map(s=>s.start_tower_no+'—'+s.end_tower_no).join('、')},[{start_tower_id:ends[0],end_tower_id:ends[1],length:''}])}
function splitAt(index:number){const row=rows.value[index];if(!row.insert_id)return;const oldEnd=row.end_tower_id;row.end_tower_id=row.insert_id;rows.value.splice(index+1,0,{start_tower_id:row.insert_id,end_tower_id:oldEnd,length:''});row.length='';delete row.insert_id}
async function saveReplace(){busy.value=true;error.value='';try{const r=await api('/ledger/lines/'+props.lineId+'/replace-spans','POST',{version:lineChoice.value!.version,topology_token:workspace.value!.topology_token,old_ids:form.old_ids,rows:rows.value,reason:form.reason,idempotency_key:requestKey.value});await saved(r,'档距变更已保存，原档距及其需求引用保留在历史中')}catch(e){report(e)}finally{busy.value=false}}
function confirmDelete(kind:string,row:Rec){resetEditor('delete',{kind,id:row.id,version:row.version,label:kind==='lines'?row.name:kind==='towers'?row.tower_no:row.start_tower_no+'—'+row.end_tower_no,reason:''})}
async function removeRecord(){busy.value=true;try{const r=await api('/ledger/'+form.kind+'/'+form.id,'DELETE',{version:form.version,reason:form.reason,idempotency_key:requestKey.value});await saved({...r,line_id:form.kind==='lines'?'':props.lineId},'记录已删除');towerView.value=null}catch(e){report(e)}finally{busy.value=false}}
function selectTowerList(clear=false){for(const t of filteredTowers.value)if(t.status==='active')selectedTowers[t.id]=!clear}
function selectSpanList(clear=false){for(const s of currentSpans.value)if(s.status!=='retired')selectedSpans[s.id]=!clear}
function neighbours(id:string){return currentSpans.value.filter(s=>s.status!=='retired'&&(s.start_tower_id===id||s.end_tower_id===id)).map(s=>({id:s.start_tower_id===id?s.end_tower_id:s.start_tower_id,name:s.start_tower_id===id?s.end_tower_no:s.start_tower_no}))}
function launchDemands(kind:string){if(kind==='spans'){const spans=chosenSpans.value.filter(s=>s.status==='active');if(!spans.length){error.value='请先选择已填写长度的档距';return}emit('demands',{kind:'span',line_id:props.lineId,rows:spans})}else emit('demands',{kind:'tower',line_id:props.lineId,rows:chosenTowers.value})}
const actionLabel=(s:string)=>({create:'新建线路',update:'线路资料调整',delete:'删除线路',add_towers:'添加杆塔',update_tower:'杆塔调整',delete_tower:'删除杆塔',physical_update:'实际杆塔公共属性调整',bind_shared:'共塔关联变更',reorder:'沿线顺序调整',add_spans:'添加档距',update_span:'档距长度调整',delete_span:'删除档距',replace_spans:'拆档 / 合档'} as Rec)[s]||'台账变更';
function unload(event:BeforeUnloadEvent){if(dirty.value){event.preventDefault();event.returnValue=''}}
onMounted(()=>{void loadData();window.addEventListener('beforeunload',unload)});onBeforeUnmount(()=>{loadVersion++;window.removeEventListener('beforeunload',unload)});
watch(()=>props.lineId,id=>{if(id&&workspace.value?.line.id!==id)void loadData(id)});
watch(tab,value=>emit('update:focusTab',value));
watch(()=>props.focusTab,value=>{if(value)tab.value=value});watch(()=>props.focusTower,id=>{if(id)void showTower(id)});
watch([query,queryLine,()=>props.view],()=>queryPage.value=1);
</script>
<template>
 <div class="ledger-workspace">
  <p v-if="visibleError" class="alert error" role="alert">{{visibleError}} <button type="button" @click="error=''">×</button></p><p v-if="success" class="alert ok" role="status">{{success}}</p>
  <template v-if="view!=='lines'">
   <section class="panel"><div class="section-header"><h2>{{view==='towers'?'杆塔查询':'档距查询'}}</h2><button class="secondary" @click="loadData()">刷新</button></div><div class="toolbar"><label><span class="field-caption">线路筛选</span><select v-model="queryLine"><option value="">全部线路</option><option v-for="l in lines" :key="l.id" :value="l.id">{{l.name}}</option></select></label><label><span class="field-caption">查询关键词</span><input v-model="query" placeholder="线路、杆塔号或型号"/></label></div>
    <div class="table-wrap"><table><thead><tr><th>线路</th><th>{{view==='towers'?'杆塔号':'起止杆塔'}}</th><th>{{view==='towers'?'结构 / 型号':'档距长度（米）'}}</th><th>状态</th><th></th></tr></thead><tbody><tr v-for="r in pageRows" :key="r.id"><td>{{r.line_name}}</td><td>{{r.tower_no||r.start_tower_no+'—'+r.end_tower_no}}</td><td>{{view==='towers'?[r.tower_type,r.model].filter(Boolean).join(' / ')||'未填写':qty(r.length_scaled)}}</td><td>{{stateName(r.status)}}</td><td><button class="link" @click="openQuery(r)">在线路中查看</button></td></tr><tr v-if="!queryRows.length"><td colspan="5" class="empty">没有符合条件的记录</td></tr></tbody></table></div><div class="ledger-pagination"><span>共 {{queryRows.length}} 条</span><button :disabled="queryPage<=1" @click="queryPage--">上一页</button><span>{{queryPage}} / {{Math.max(1,Math.ceil(queryRows.length/30))}}</span><button :disabled="queryPage*30>=queryRows.length" @click="queryPage++">下一页</button></div>
   </section>
  </template>
  <div v-else class="ledger-layout">
   <aside class="ledger-directory panel"><div class="section-header"><h2>线路目录</h2><button v-if="canWrite" class="link" aria-label="新建线路" @click="lineForm()">＋ 新建线路</button></div>
    <label><span class="field-caption">搜索线路</span><input v-model="filter" placeholder="输入主线或支线名称"/></label><label><span class="field-caption">电压等级筛选</span><select v-model="voltageFilter"><option value="">全部电压等级</option><option v-for="v in voltage" :key="v.id" :value="v.id">{{v.name}}</option></select></label>
    <div class="ledger-tree"><div v-for="l in tree" :key="l.id"><button class="ledger-line" :class="{selected:lineId===l.id}" @click="selectLine(l.id)"><strong>{{l.name}}</strong><small>{{l.voltage_name}} · 主线 · {{l.tower_count}} 基</small></button><button v-for="child in l.children" :key="child.id" class="ledger-line branch" :class="{selected:lineId===child.id}" @click="selectLine(child.id)"><strong>└ {{child.name}}</strong><small>支线{{child.setup_status==='draft'?' · 接入点待确认':''}}</small></button></div><p v-if="!tree.length" class="empty">{{lines.length?'没有符合条件的线路':'先新建一条主线，再添加杆塔'}}</p></div>
   </aside>
   <div class="ledger-main" :aria-busy="loading">
    <section v-if="lineChoice" class="panel ledger-summary"><div class="section-header"><div><span class="tag">{{lineChoice.line_kind==='main'?'主线':'支线'}}</span><h2>{{lineChoice.name}}</h2><p class="muted">{{lineChoice.voltage_name}} · {{stateName(lineChoice.status)}}</p><p v-if="lineChoice.line_kind==='branch'" class="muted">所属主线：{{lineChoice.parent_name}} · 接入杆塔：{{lineChoice.junction_tower_no||'待确认'}}</p></div><div class="actions"><button v-if="canWrite&&lineChoice.line_kind==='main'" class="secondary" @click="lineForm(true)">新增支线</button><button v-if="canWrite" class="secondary" @click="editLine">编辑线路</button><button class="light" @click="loadData()">刷新</button></div></div>
     <div class="ledger-tabs"><button v-for="t in [{id:'towers',name:'杆塔'},{id:'spans',name:'档距'},{id:'info',name:'线路信息'},{id:'history',name:'变更记录'}]" :key="t.id" :class="{active:tab===t.id}" @click="tab=t.id">{{t.name}}</button></div>
    </section>
    <section v-if="!lineChoice" class="panel empty"><p>从左侧选择线路，或新建主线开始录入。</p><button v-if="canWrite" class="primary" @click="lineForm()">新建主线</button></section>
    <template v-else>
     <p v-if="lineChoice.setup_status==='draft'" class="alert">支线接入点待确认。<button v-if="canWrite" class="link" @click="editLine">继续完善支线</button></p>
     <section v-if="tab==='towers'" class="panel"><div class="section-header"><div><h2>线路杆塔</h2><p class="muted">编号与沿线顺序分别维护；共塔公共属性只保存一份。</p></div><div v-if="canWrite" class="actions"><button class="secondary" :disabled="!ready" @click="addTower(true)">批量添加杆塔</button><button class="primary" :disabled="!ready" @click="addTower()">新增杆塔</button></div></div>
      <div class="toolbar"><label><span class="field-caption">筛选杆塔</span><input v-model="towerSearch" placeholder="杆塔号、结构或型号"/></label><button class="light" @click="selectTowerList()">全选当前列表</button><button class="light" @click="selectTowerList(true)">清空选择</button><button v-if="canWrite" class="light" :disabled="!ownTowers.length" @click="openReorder">调整沿线顺序</button><button v-if="canWrite" class="secondary" :disabled="!chosenTowers.filter(t=>!t.is_junction).length" @click="openShared()">批量关联共塔</button><button v-if="canWrite" class="secondary" :disabled="!chosenTowers.length" @click="launchDemands('towers')">按所选杆塔新建需求（{{chosenTowers.length}}）</button></div>
      <div class="table-wrap"><table><thead><tr><th>选择</th><th>顺序</th><th>杆塔号</th><th>结构 / 型号</th><th>共塔情况</th><th>相邻杆塔</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="(t,index) in filteredTowers" :key="t.id" :class="{'ledger-highlight':highlight.includes(t.id)}"><td><input v-model="selectedTowers[t.id]" type="checkbox" :disabled="t.status!=='active'" :aria-label="'选择杆塔 '+t.tower_no"/></td><td>{{t.is_junction?'接入点':ownTowers.findIndex(r=>r.id===t.id)+1}}</td><td><button class="link" @click="showTower(t.id)">{{t.tower_no}}</button><small v-if="t.is_junction" class="muted">引用 {{t.line_name}}</small></td><td>{{t.tower_type||'未填写'}}<small>{{t.model}}</small></td><td>{{t.shared_count>1?'关联 '+t.shared_count+' 个线路位置':'独立杆塔'}}</td><td><button v-for="n in neighbours(t.id)" :key="n.id" class="link" @click="showTower(n.id)">{{n.name}}</button><span v-if="!neighbours(t.id).length">未建立档距</span></td><td>{{stateName(t.status)}}</td><td class="actions"><button class="link" @click="showTower(t.id)">详情</button><template v-if="canWrite&&!t.is_junction"><button class="link" @click="editTower(t)">编辑</button><button class="link" :disabled="!ready||t.status==='inactive'" @click="addTower(false,t.id)">后插入</button></template></td></tr><tr v-if="!filteredTowers.length"><td colspan="8" class="empty">尚无杆塔。可一次添加多基，随后生成档距。</td></tr></tbody></table></div>
     </section>
     <section v-if="tab==='spans'" class="panel"><div class="section-header"><div><h2>线路档距</h2><p class="muted">只维护起止杆塔与档距长度。未填写长度不会按零计算。</p></div><div v-if="canWrite" class="actions"><button class="secondary" :disabled="!ready||nodes.length<2" @click="generateSpans">按杆塔顺序生成</button><button class="primary" :disabled="!ready||nodes.length<2" @click="addSpan">新增档距</button></div></div>
      <div class="ledger-selection"><button class="light" @click="selectSpanList()">全选当前档距</button><button class="light" @click="selectSpanList(true)">清空所选档距</button><label class="ledger-check"><input v-model="showRetired" type="checkbox"/>显示历史档距</label><button v-if="canWrite" class="secondary" :disabled="!chosenSpans.length" @click="openReplace">拆档 / 合档</button><button v-if="canWrite" class="secondary" :disabled="!chosenSpans.some(s=>s.status==='active')" @click="launchDemands('spans')">按所选档距新建需求</button></div>
      <div class="table-wrap"><table><thead><tr><th>选择</th><th>起点杆塔</th><th>终点杆塔</th><th>档距长度（米）</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="s in currentSpans" :key="s.id" :class="{'ledger-highlight':highlight.includes(s.id)}"><td><input v-model="selectedSpans[s.id]" type="checkbox" :disabled="s.status==='retired'" :aria-label="'选择档距 '+s.start_tower_no+'—'+s.end_tower_no"/></td><td><button class="link" @click="showTower(s.start_tower_id)">{{s.start_tower_no}}</button></td><td><button class="link" @click="showTower(s.end_tower_id)">{{s.end_tower_no}}</button></td><td>{{qty(s.length_scaled)}}</td><td>{{stateName(s.status)}}</td><td class="actions"><template v-if="canWrite&&s.status!=='retired'"><button class="link" @click="editSpan(s)">{{s.length_scaled===null?'填写长度':'编辑长度'}}</button><button class="link" @click="confirmDelete('spans',s)">删除</button></template><span v-if="s.demand_count">{{s.demand_count}} 条需求引用</span></td></tr><tr v-if="!currentSpans.length"><td colspan="6" class="empty">尚无档距，请先确认杆塔顺序，再生成候选连接。</td></tr></tbody></table></div>
     </section>
     <section v-if="tab==='info'" class="panel"><h2>线路信息</h2><div class="info-grid"><div v-for="[key,label] in [['name','线路名称'],['voltage_name','电压等级'],['start_label','起点位置'],['end_label','终点位置']]" :key="key"><small>{{label}}</small><strong>{{lineChoice[key]||'未填写'}}</strong></div></div><button v-if="canWrite" class="light" @click="confirmDelete('lines',lineChoice)">删除误录线路</button></section>
     <section v-if="tab==='history'" class="panel"><h2>变更记录</h2><article v-for="h in workspace!.history" :key="h.id" class="ledger-history"><strong>{{actionLabel(h.action)}}</strong><p>{{h.reason||'初始录入'}} · {{h.actor_name||'用户'}} · {{new Date(h.created_at).toLocaleString()}}</p></article><p v-if="!workspace!.history.length" class="empty">尚无线路工作台变更记录，原台账命名历史仍保留在杆塔详情。</p></section>
    </template>
   </div>
  </div>
  <FormModal :open="!!editor" :title="title" :error="visibleError" size="wide" @close="closeEditor">
   <form v-if="editor==='line'" v-form-validation novalidate class="form-grid" @submit.prevent="saveLine()">
    <label><span class="field-caption">线路类型</span><select v-model="form.line_kind" :disabled="!!form.id"><option value="main">主线</option><option value="branch">支线</option></select></label><label><span class="field-caption">线路名称</span><input v-model="form.name" required/></label>
    <label v-if="form.line_kind==='main'"><span class="field-caption">电压等级</span><select v-model="form.voltage_level_id" :disabled="!!form.id" required><option value="">请选择</option><option v-for="v in voltage.filter(v=>v.status==='active'||v.id===form.voltage_level_id)" :key="v.id" :value="v.id">{{v.name}}</option></select></label>
    <template v-else><label><span class="field-caption">所属主线</span><select v-model="form.parent_line_id" :disabled="!!form.id" required><option value="">请选择</option><option v-for="l in lines.filter(l=>l.line_kind==='main'&&l.status==='active')" :key="l.id" :value="l.id">{{l.name}}</option></select></label><label><span class="field-caption">接入杆塔</span><select v-model="form.junction_tower_id" :required="form.setup_status!=='draft'"><option value="">待确认，可保存草稿</option><option v-for="t in allTowers.filter(t=>t.line_id===form.parent_line_id&&t.status==='active')" :key="t.id" :value="t.id">{{t.tower_no}} · {{t.model||t.tower_type||'型号未填写'}}</option></select></label><p class="wide muted">支线继承主线电压；接入点引用主线杆塔，不另建实际杆塔。</p></template>
    <label><span class="field-caption">起点位置</span><input v-model="form.start_label"/></label><label><span class="field-caption">终点位置</span><input v-model="form.end_label"/></label><label v-if="form.id"><span class="field-caption">状态</span><select v-model="form.status"><option value="active">在用</option><option value="inactive">停用</option></select></label><label v-if="form.id" class="wide"><span class="field-caption">变更原因</span><input v-model="form.reason" required/></label>
    <div class="wide form-actions"><button type="button" class="light" @click="closeEditor">取消</button><button v-if="form.line_kind==='branch'&&!form.junction_tower_id" type="button" class="secondary" :disabled="busy||!form.name||!form.parent_line_id" @click="saveLine(true)">保存支线草稿</button><button class="primary" :disabled="busy">保存线路</button></div>
   </form>
   <form v-if="['tower-add','tower-batch'].includes(editor)" v-form-validation novalidate @submit.prevent="saveTowers">
    <p class="muted">所属线路：{{lineChoice?.name}}。内部编号自动生成。</p><div class="form-grid"><label><span class="field-caption">插入位置</span><select v-model="form.after_tower_id"><option value="">追加到线路末尾</option><option v-for="t in ownTowers.filter(t=>t.status!=='inactive')" :key="t.id" :value="t.id">{{t.tower_no}} 之后</option></select></label><label v-if="editor==='tower-add'"><span class="field-caption">实际杆塔</span><select v-model="form.mode"><option value="new">新建实际杆塔</option><option value="existing">关联已有线路杆塔</option></select></label></div>
    <template v-if="editor==='tower-batch'"><div class="ledger-selection"><label class="ledger-check"><input v-model="inputMode" type="radio" value="range"/>连续编号</label><label class="ledger-check"><input v-model="inputMode" type="radio" value="paste"/>粘贴编号</label></div><div v-if="inputMode==='range'" class="form-grid"><label><span class="field-caption">编号起点</span><input v-model="rangeStart" type="number" min="0"/></label><label><span class="field-caption">编号终点</span><input v-model="rangeEnd" type="number" min="0"/></label><label><span class="field-caption">补零位数</span><input v-model="numberWidth" type="number" min="1" max="10"/></label><label><span class="field-caption">编号前缀</span><input v-model="numberPrefix" placeholder="可留空，如 #"/></label></div><label v-else><span class="field-caption">粘贴杆塔编号</span><textarea v-model="pasteNumbers" rows="4" placeholder="每行一基，支持 001A、015+1 等编号"/></label></template>
    <fieldset v-if="form.mode!=='existing'" class="ledger-fieldset"><legend>共同属性（选填）</legend><div class="form-grid"><label><span class="field-caption">结构类型</span><input v-model="common.tower_type" list="ledger-structures"/></label><label><span class="field-caption">型号</span><input v-model="common.model"/></label><label><span class="field-caption">塔高（米）</span><input v-model="common.height" data-validate="quantity" inputmode="decimal"/></label><label><span class="field-caption">用途</span><input v-model="common.purpose" list="ledger-purposes"/></label><template v-if="editor==='tower-add'"><label><span class="field-caption">经度</span><input v-model="common.longitude" type="number" step="any" min="-180" max="180"/></label><label><span class="field-caption">纬度</span><input v-model="common.latitude" type="number" step="any" min="-90" max="90"/></label><label><span class="field-caption">投运日期</span><input v-model="common.commissioned_on" type="date"/></label></template></div></fieldset>
    <div v-if="editor==='tower-batch'" class="actions"><button type="button" class="secondary" @click="generateNumbers">生成逐基预览</button><button type="button" class="light" @click="applyCommon()">共同属性仅填空值</button><button type="button" class="light" @click="applyCommon(true)">共同属性覆盖勾选行</button></div>
    <label v-if="form.mode==='existing'||editor==='tower-batch'"><span class="field-caption">查找已有杆塔的线路</span><select v-model="sourceLine"><option value="">其他全部线路</option><option v-for="l in lines.filter(l=>l.id!==lineId)" :key="l.id" :value="l.id">{{l.name}}</option></select></label>
    <div class="table-wrap"><table><thead><tr><th v-if="editor==='tower-batch'">应用共同属性</th><th>杆塔号 <span class="required-star">*</span></th><th v-if="editor==='tower-batch'">结构 / 型号</th><th v-if="editor==='tower-batch'||form.mode==='existing'">关联已有杆塔</th><th>回路位置</th><th v-if="editor==='tower-batch'"></th></tr></thead><tbody><tr v-for="(r,index) in rows" :key="index" :data-row-index="index"><td v-if="editor==='tower-batch'"><input v-model="r.selected" type="checkbox" :aria-label="'应用共同属性 '+(index+1)"/></td><td><input v-model="r.tower_no" :aria-label="'杆塔号 '+(index+1)" required/></td><td v-if="editor==='tower-batch'"><input v-model="r.tower_type" :aria-label="'结构类型 '+(index+1)" list="ledger-structures"/><input v-model="r.model" :aria-label="'型号 '+(index+1)"/></td><td v-if="editor==='tower-batch'||form.mode==='existing'"><select v-model="r.physical_tower_id" :required="form.mode==='existing'" :aria-label="'关联已有杆塔 '+(index+1)"><option value="">{{editor==='tower-batch'?'新建实际杆塔':'请选择'}}</option><option v-for="t in lookup" :key="t.id" :value="t.physical_tower_id">{{t.line_name}} {{t.tower_no}} · {{t.model||t.tower_type||'未填写型号'}}</option></select><small v-if="r.physical_tower_id">采用该实际杆塔的公共属性</small></td><td><input v-model="r.circuit_position" :aria-label="'回路位置 '+(index+1)" placeholder="左、右等，可留空"/></td><td v-if="editor==='tower-batch'"><button type="button" class="link" @click="rows.splice(index,1);preview=null">移除</button></td></tr></tbody></table></div>
    <p v-if="preview&&previewHash===JSON.stringify(towerPayload())" class="alert ok">预检通过，共 {{rows.length}} 基。确认编号、顺序和共塔关系后保存。</p><div class="form-actions"><button type="button" class="light" @click="closeEditor">取消</button><button class="primary" :disabled="busy||!rows.length">{{editor==='tower-batch'?(previewHash===JSON.stringify(towerPayload())?'确认保存 '+rows.length+' 基':'预检并继续'):'保存杆塔'}}</button></div>
   </form>
   <form v-if="editor==='whole-replace'" v-form-validation novalidate class="form-grid" @submit.prevent="saveWholeReplacement">
     <p class="muted wide">该实体塔关联多个线路位置，实际整塔更换须逐项确认全部回路。单回路资料关联错误请使用“关联共塔”中的纠错功能。</p>
     <label class="wide"><span class="field-caption">目标实体塔</span>
       <select v-model="form.target_physical_tower_id" required><option value="">请选择已登记的目标实体塔</option>
        <option v-for="t in replacementTargets" :key="t.id" :value="t.id">{{t.tower_code}} · {{t.model||t.tower_type||'未填写型号'}}</option>
       </select>
     </label>
     <div class="wide scope-item"><strong>受影响的全部在用回路（{{rows.length}}）</strong>
       <label v-for="t in rows" :key="t.id" class="ledger-check">
        <input v-model="t.checked" type="checkbox" :aria-label="'确认更换 '+t.line_name+' '+t.tower_no" required/>
        {{t.line_name}} · {{t.tower_no}}（版本 {{t.version}}）
       </label>
     </div>
     <label class="wide"><span class="field-caption">整体更换依据</span><textarea v-model="form.reason" required rows="3" placeholder="现场依据及影响范围核实情况"/></label>
     <div class="wide form-actions"><button type="button" class="light" @click="closeEditor">取消</button><button class="primary" :disabled="busy||rows.some((t:Rec)=>!t.checked)">确认整塔更换</button></div>
   </form>
   <form v-if="['tower-edit','tower-replace'].includes(editor)" v-form-validation novalidate class="form-grid" @submit.prevent="saveTower">
    <p class="wide muted">所属线路：{{lineChoice?.name}}。{{editor==='tower-replace'?'为当前线路位置登记新的实际杆塔，原实体及业务依据保留历史。':'杆塔号只修改当前线路，公共属性修改会影响关联线路。'}}</p>
    <label><span class="field-caption">杆塔号</span><input v-model="form.tower_no" required/></label><label><span class="field-caption">回路位置</span><input v-model="form.circuit_position"/></label><label><span class="field-caption">状态</span><select v-model="form.status"><option value="active">在用</option><option value="draft">待完善</option><option value="inactive">停用</option></select></label><label><span class="field-caption">结构类型</span><input v-model="form.physical.tower_type" list="ledger-structures"/></label><label><span class="field-caption">型号</span><input v-model="form.physical.model"/></label><label><span class="field-caption">塔高（米）</span><input v-model="form.physical.height" data-validate="quantity"/></label><label><span class="field-caption">用途</span><input v-model="form.physical.purpose" list="ledger-purposes"/></label><label><span class="field-caption">投运日期</span><input v-model="form.physical.commissioned_on" type="date"/></label><label><span class="field-caption">经度</span><input v-model="form.physical.longitude" type="number" step="any" min="-180" max="180"/></label><label><span class="field-caption">纬度</span><input v-model="form.physical.latitude" type="number" step="any" min="-90" max="90"/></label>
    <div v-if="editor==='tower-edit'&&commonChanged&&towerView!.shared_with.length>1" class="wide alert"><p>公共属性将同时影响：{{towerView!.shared_with.map((r:Rec)=>r.line_name+' '+r.tower_no).join('、')}}</p><label class="ledger-check"><input v-model="form.confirm_shared" type="checkbox" required aria-label="确认共同属性修改影响"/>我已核对关联线路</label></div><label class="wide"><span class="field-caption">变更原因</span><input v-model="form.reason" required/></label><div class="wide form-actions"><button type="button" class="light" @click="closeEditor">取消</button><button class="primary" :disabled="busy">保存杆塔变更</button></div>
   </form>
   <form v-if="editor==='shared'" v-form-validation novalidate @submit.prevent="saveShared"><p>请选择另一条线路上的对应杆塔。关联后采用所选实际杆塔的公共属性，原需求定位不会自动改写。</p><label><span class="field-caption">目标线路筛选</span><select v-model="sourceLine"><option value="">其他全部线路</option><option v-for="l in lines.filter(l=>l.id!==lineId)" :key="l.id" :value="l.id">{{l.name}}</option></select></label><div v-for="(r,index) in rows" :key="r.source_id" class="scope-item" :data-row-index="index"><strong>当前线路 {{r.source_name}}</strong><label><span class="field-caption">对应杆塔</span><select v-model="r.target_id" :aria-label="'对应杆塔 '+(index+1)" required><option value="">请选择</option><option v-for="t in lookup" :key="t.id" :value="t.id">{{t.line_name}} {{t.tower_no}} · {{t.tower_type}} {{t.model}}</option></select></label></div><p v-if="preview" class="alert ok">已预览 {{preview.pairs.length}} 对关系，关联前请核实实际为同一基杆塔。涉及 {{preview.pairs.reduce((n:number,p:Rec)=>n+p.affected_demands,0)}} 条既有需求，保留原快照。</p><label><span class="field-caption">关联依据</span><textarea v-model="form.reason" required/></label><div class="form-actions"><button type="button" class="light" @click="closeEditor">取消</button><button class="primary" :disabled="busy||!rows.length">{{preview?'确认共塔关联':'预览共塔关系'}}</button></div></form>
   <form v-if="editor==='reorder'" v-form-validation novalidate @submit.prevent="saveOrder"><p class="muted">只调整沿线顺序，已有档距的起止杆塔保持不变。</p><ol class="ledger-order"><li v-for="(r,index) in rows" :key="r.id"><strong>{{r.tower_no}}</strong><div class="actions"><button type="button" :disabled="index===0" :aria-label="'上移 '+r.tower_no" @click="move(index,-1)">上移</button><button type="button" :disabled="index===rows.length-1" :aria-label="'下移 '+r.tower_no" @click="move(index,1)">下移</button></div></li></ol><label><span class="field-caption">调整原因</span><input v-model="form.reason" required/></label><div class="form-actions"><button type="button" class="light" @click="closeEditor">取消</button><button class="primary" :disabled="busy">确认调整顺序</button></div></form>
   <form v-if="['span-add','span-edit'].includes(editor)" v-form-validation novalidate class="form-grid" @submit.prevent="saveSpans"><p class="wide muted">所属线路：{{lineChoice?.name}}。名称由起止杆塔自动生成。</p><template v-if="editor==='span-add'"><label><span class="field-caption">起点杆塔</span><select v-model="form.start_tower_id" required><option value="">请选择</option><option v-for="t in endpointOptions" :key="t.id" :value="t.id">{{t.tower_no}}{{t.is_junction?'（主线接入点）':''}}</option></select></label><label><span class="field-caption">终点杆塔</span><select v-model="form.end_tower_id" required><option value="">请选择</option><option v-for="t in endpointOptions" :key="t.id" :value="t.id">{{t.tower_no}}</option></select></label></template><p v-else class="wide">{{form.start_tower_no}}—{{form.end_tower_no}}</p><p v-if="form.demand_count" class="wide alert">已有 {{form.demand_count}} 条需求引用。修改长度会保留原需求快照，后续关联项目需重新核实位置。</p><label><span class="field-caption">档距长度（米）</span><input v-model="form.length" data-validate="quantity" inputmode="decimal" placeholder="未确定可留空暂存"/></label><label v-if="editor==='span-edit'" class="wide"><span class="field-caption">调整依据</span><input v-model="form.reason" required/></label><div class="wide form-actions"><button type="button" class="light" @click="closeEditor">取消</button><button class="primary" :disabled="busy">{{form.length?'保存档距':'保存待完善档距'}}</button></div></form>
   <form v-if="editor==='span-batch'" v-form-validation novalidate @submit.prevent="saveSpans"><p>按当前杆塔顺序生成候选，未选中的杆塔间隙不会自动跨接。已存在 {{rows.filter(r=>r.existing_id).length}} 档，跳过重复建立。</p><label><span class="field-caption">批量粘贴长度</span><textarea v-model="pasteLengths" rows="3" placeholder="每行一个长度，对应勾选的新档距"/></label><button type="button" class="secondary" @click="pasteSpanLengths">填入所选档距</button><div class="table-wrap"><table><thead><tr><th>建立</th><th>起点杆塔</th><th>终点杆塔</th><th>档距长度（米）</th></tr></thead><tbody><tr v-for="(r,index) in rows" :key="index" :data-row-index="index"><td><input v-model="r.selected" type="checkbox" :disabled="!!r.existing_id" :aria-label="'建立档距 '+(index+1)"/></td><td>{{r.start_tower_no}}</td><td>{{r.end_tower_no}}</td><td><span v-if="r.existing_id">已存在 · {{r.length||'未填写'}}</span><input v-else v-model="r.length" :disabled="r.selected===false" data-validate="quantity" :aria-label="'档距长度 '+r.start_tower_no+'—'+r.end_tower_no" placeholder="未确定可暂存"/></td></tr></tbody></table></div><div class="form-actions"><button type="button" class="light" @click="closeEditor">取消</button><button class="primary" :disabled="busy||!selectedRows.length">确认建立 {{selectedRows.length}} 档</button></div></form>
   <form v-if="editor==='replace'" v-form-validation novalidate @submit.prevent="saveReplace"><p>原档距：{{form.old_names}}。变更必须保持外侧两端不变，原记录将保留为历史。</p><div v-for="(r,index) in rows" :key="index" class="scope-item form-grid" :data-row-index="index"><label><span class="field-caption">起点杆塔</span><select v-model="r.start_tower_id" required :aria-label="'新档起点 '+(index+1)"><option v-for="t in endpointOptions" :key="t.id" :value="t.id">{{t.tower_no}}</option></select></label><label><span class="field-caption">终点杆塔</span><select v-model="r.end_tower_id" required :aria-label="'新档终点 '+(index+1)"><option v-for="t in endpointOptions" :key="t.id" :value="t.id">{{t.tower_no}}</option></select></label><label><span class="field-caption">新档长度（米）</span><input v-model="r.length" data-validate="quantity" :aria-label="'新档长度 '+(index+1)"/></label><label><span class="field-caption">从现有杆塔中选择插入点</span><select v-model="r.insert_id" :aria-label="'插入杆塔 '+(index+1)"><option value="">不拆分此行</option><option v-for="t in endpointOptions.filter(t=>t.id!==r.start_tower_id&&t.id!==r.end_tower_id)" :key="t.id" :value="t.id">{{t.tower_no}}</option></select></label><div class="wide actions"><button type="button" class="secondary" :disabled="!r.insert_id" @click="splitAt(index)">在此杆塔拆为两档</button><button v-if="rows.length>1" type="button" class="light" @click="rows.splice(index,1)">移除此行</button></div></div><label><span class="field-caption">拆档 / 合档依据</span><textarea v-model="form.reason" required/></label><div class="form-actions"><button type="button" class="light" @click="closeEditor">取消</button><button class="primary" :disabled="busy">确认档距变更</button></div></form>
   <form v-if="editor==='delete'" v-form-validation novalidate @submit.prevent="removeRecord"><p>删除“{{form.label}}”？已有业务引用的记录不能直接删除，系统会保留关联依据。</p><label><span class="field-caption">删除原因</span><input v-model="form.reason" required/></label><div class="form-actions"><button type="button" class="light" @click="closeEditor">取消</button><button class="primary" :disabled="busy">确认删除</button></div></form>
  </FormModal>
  <FormModal :open="discard" title="放弃未保存的修改？" @close="discard=false"><p>已填写的内容尚未保存，关闭后将丢弃本次修改。</p><div class="form-actions"><button class="secondary" @click="discard=false">继续编辑</button><button class="primary" @click="discardEditor">放弃修改</button></div></FormModal>
  <section v-if="towerView&&!editor" class="detail-overlay" @click.self="towerView=null"><div class="detail-panel"><div class="section-header"><h2>杆塔 {{towerView.tower_no}}</h2><button class="light" @click="towerView=null">关闭 ×</button></div><h3>当前线路位置</h3><p>{{lines.find(l=>l.id===towerView!.line_id)?.name}} · {{towerView.tower_no}} · {{stateName(towerView.status)}}</p><h3>实际杆塔公共属性</h3><div class="info-grid"><div v-for="[key,label] in [['tower_type','结构类型'],['model','型号'],['purpose','用途']]" :key="key"><small>{{label}}</small><strong>{{towerView.physical?.[key]||'未填写'}}</strong></div><div><small>塔高（米）</small><strong>{{qty(towerView.physical?.height_scaled)}}</strong></div></div><h3>关联线路</h3><p v-for="t in towerView.shared_with" :key="t.id"><button class="link" @click="towerView=null;selectLine(t.line_id)">{{t.line_name}} {{t.tower_no}}</button> {{t.circuit_position}}</p><h3>相邻档距</h3><p v-for="s in towerView.spans" :key="s.id">{{s.line_name}} {{s.start_tower_no}}—{{s.end_tower_no}} · {{qty(s.length_scaled)}} 米 · {{stateName(s.status)}}</p><p v-if="!towerView.spans.length" class="muted">尚未建立相邻档距</p><p class="muted">{{towerView.demand_count}} 条需求引用</p><div v-if="canWrite&&towerView.line_id===lineId" class="form-actions"><button class="secondary" @click="editTower(towerView)">编辑杆塔</button><button class="secondary" @click="openShared(towerView)">关联共塔</button><button class="secondary" @click="editTower(towerView,true)">实际换塔</button><button class="light" @click="confirmDelete('towers',towerView)">删除误录杆塔</button></div><h3>命名与实体变更历史</h3><p v-for="h in [...towerView.names,...towerView.bindings].sort((a,b)=>b.valid_from.localeCompare(a.valid_from))" :key="h.id" class="history">{{new Date(h.valid_from).toLocaleString()}} · {{h.tower_no||({initial:'初始关联',correction:'关联纠错',replacement:'实际换塔'} as Rec)[h.change_kind]}} · {{h.reason}}</p></div></section>
  <datalist id="ledger-structures"><option v-for="i in optionItems('tower_structure')" :key="i.id" :value="i.name"/></datalist><datalist id="ledger-purposes"><option v-for="i in optionItems('tower_purpose')" :key="i.id" :value="i.name"/></datalist>
 </div>
</template>
